rules.pseudocode:
newSession = ctx.Date(0) != ctx.Date(1);
if (newSession) { barsIntoSession = 0; orHigh = high[0]; orLow = low[0]; orSet = false }
else { barsIntoSession = barsIntoSession + 1; if (!orSet) { orHigh = MaxList(orHigh, high[0]); orLow = MinList(orLow, low[0]) } }
if (!orSet && barsIntoSession >= openingBars - 1) orSet = true;
orHeight = orHigh - orLow;
return orSet

newSession = ctx.Date(0) != ctx.Date(1);
if (newSession) { push(sessionHigh - sessionLow) into dailyRanges; sessionHigh = high[0]; sessionLow = low[0] }
else { sessionHigh = MaxList(sessionHigh, high[0]); sessionLow = MinList(sessionLow, low[0]) }
adr = average(dailyRanges, dayLookback);
return count(dailyRanges) >= dayLookback

sessionAvgBarRange = sessionRangeSum / barsIntoSession;  /* both reset at the session date change */
stopDistance = stopMultiple * sessionAvgBarRange;
ctx.OpenPositionLoss() >= stopDistance * ctx.BigPointValue()

/* research: needs the realized MAE of the first closed trade of the session, persisted across later independent trades */
sessionMinStopTicks = firstTradeMaeTicksToday();
stopDistanceTicks = MaxList(defaultStopTicks, sessionMinStopTicks + 1);
ctx.OpenPositionLoss() >= stopDistanceTicks * tickSize * ctx.BigPointValue()

if (ctx.Date(0) != ctx.Date(1)) { trendFromOpen = 0; firstBarHigh = high[0]; firstBarLow = low[0] }
else {
  if (trendFromOpen == 0 && close[0] > firstBarHigh) trendFromOpen = 1;
  if (trendFromOpen == 0 && close[0] < firstBarLow) trendFromOpen = -1;
  if (trendFromOpen == 1 && close[0] < firstBarLow) trendFromOpen = 0;
  if (trendFromOpen == -1 && close[0] > firstBarHigh) trendFromOpen = 0
}
return trendFromOpen == 1

if (barsIntoSession == firstHourBars) {
  morningLegHeight = absvalue(close[0] - sessionOpen);
  if (morningLegHeight >= minLegAtr * WFSafe_AvgTrueRange(atrLength)) morningLegDirection = sign(close[0] - sessionOpen) else morningLegDirection = 0
}
return morningLegDirection == 1

/* research: needs the prior session classified as having reversed late */
priorLateMove = priorSessionClose - priorSessionPriceAtLateWindowStart;
priorEarlyMove = priorSessionPriceAtLateWindowStart - priorSessionOpen;
hadLateReversal = sign(priorLateMove) != sign(priorEarlyMove) && absvalue(priorLateMove) >= reversalSizeAtr * WFSafe_AvgTrueRange(atrLength);
return hadLateReversal && priorLateMove > 0

if (ctx.Date(0) != ctx.Date(1)) tradesToday = 0;
if (ctx.MarketPosition() != 0 && ctx.MarketPosition(1) == 0) tradesToday = tradesToday + 1;
return tradesToday >= maxTradesPerDay
